const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'x' },
      { kind: 'text', payload: 'y' },
      { kind: 'text', payload: 'O' },
      { kind: 'text', payload: 'P(6,-2)' },
      { kind: 'text', payload: '第四象限' },
      { kind: 'text', payload: '6' },
      { kind: 'text', payload: '-2' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var unit = Math.min(W / 18, H / 14);
    var ox = W * 0.28;
    var oy = H * 0.36;
    var px = ox + 6 * unit;
    var py = oy + 2 * unit;
    var x0 = W * 0.06;
    var x1 = W * 0.94;
    var y0 = H * 0.94;
    var y1 = H * 0.08;

    var axisX = visualSdk.axis({ x0: x0, y0: oy, x1: x1, y1: oy, ticks: 8, tickLength: 6 });
    var axisY = visualSdk.axis({ x0: ox, y0: y0, x1: ox, y1: y1, ticks: 8, tickLength: 6 });
    var point = visualSdk.circle(px, py, 4.5);
    var dashV = [['M', px, py], ['L', px, oy]];
    var dashH = [['M', px, py], ['L', ox, py]];

    return {
      schemaVersion: 1,
      sceneId: 'fig-p-6-minus-2',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'axisX', commands: axisX },
        { id: 'axisY', commands: axisY },
        { id: 'dashV', commands: dashV },
        { id: 'dashH', commands: dashH },
        { id: 'point', commands: point }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'axisX', fill: '#26354a', stroke: { width: 2 } },
          { type: 'path', pathId: 'axisY', fill: '#26354a', stroke: { width: 2 } },
          { type: 'path', pathId: 'dashV', fill: '#7a5c2e', stroke: { width: 1.5, dash: [6, 5] } },
          { type: 'path', pathId: 'dashH', fill: '#7a5c2e', stroke: { width: 1.5, dash: [6, 5] } },
          { type: 'path', pathId: 'point', fill: '#c0392b', stroke: { width: 1 } },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: x1, y: oy - 10 }, hAlign: 'right', vAlign: 'bottom', color: '#26354a' },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: ox + 10, y: y1 }, hAlign: 'left', vAlign: 'top', color: '#26354a' },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: ox - 8, y: oy + 8 }, hAlign: 'right', vAlign: 'top', color: '#26354a' },
          { type: 'label', contentId: metrics[3].contentId, anchor: { x: px + 10, y: py - 8 }, hAlign: 'left', vAlign: 'bottom', color: '#c0392b' },
          { type: 'label', contentId: metrics[4].contentId, anchor: { x: W * 0.72, y: H * 0.78 }, hAlign: 'center', vAlign: 'middle', color: '#26354a' },
          { type: 'label', contentId: metrics[5].contentId, anchor: { x: px, y: oy + 14 }, hAlign: 'center', vAlign: 'top', color: '#26354a' },
          { type: 'label', contentId: metrics[6].contentId, anchor: { x: ox - 12, y: py }, hAlign: 'right', vAlign: 'middle', color: '#26354a' }
        ]
      }
    };
  }
};
